package com.bank.phrase;

import java.util.logging.Logger;

public class SecurityPhraseVerifier {

    private static final Logger log = Logger.getLogger(SecurityPhraseVerifier.class.getName());

    public boolean exists(char[][] board, String word) {
        for (int r = 0; r < board.length; r++)
            for (int c = 0; c < board[0].length; c++)
                if (dfs(board, r, c, word, 0)) {
                    log.info(() -> "Phrase '" + word + "' traced successfully");
                    return true;
                }
        log.warning(() -> "Phrase '" + word + "' not found on grid");
        return false;
    }

    private boolean dfs(char[][] board, int r, int c, String word, int idx) {
        if (idx == word.length()) return true;                 // fully matched
        if (r < 0 || c < 0 || r >= board.length || c >= board[0].length) return false;
        if (board[r][c] != word.charAt(idx)) return false;     // mismatch

        char tmp = board[r][c];
        board[r][c] = '#';                                     // mark visited
        boolean found = dfs(board, r + 1, c, word, idx + 1)
                     || dfs(board, r - 1, c, word, idx + 1)
                     || dfs(board, r, c + 1, word, idx + 1)
                     || dfs(board, r, c - 1, word, idx + 1);
        board[r][c] = tmp;                                     // restore (backtrack)
        return found;
    }
}
