package com.bank.phrase;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class WordSearchDemo {

    private static final Logger log = Logger.getLogger(WordSearchDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Security Phrase Verifier (Word Search)");
        char[][] board = {
            {'N', 'B', 'I'},
            {'A', 'K', 'E'},
            {'T', 'C', 'Y'}
        };
        SecurityPhraseVerifier v = new SecurityPhraseVerifier();
        log.info("NBIEY present? " + v.exists(board, "NBIEY")); // true: N→B→I→E→Y
        log.info("NBZ present? " + v.exists(board, "NBZ"));     // false
    }
}
